return ['domain'=>'wp-updates-notifier','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'es_ES','project-id-version'=>'WP Updates Notifier','pot-creation-date'=>'2026-01-01 00:00+0000','po-revision-date'=>'2026-01-01 00:00+0000','messages'=>['WP Updates Notifier'=>'WP Updates Notifier','https://wpun.cariss.dev/'=>'https://wpun.cariss.dev/','Sends an email to notify you if there are any updates for your WordPress site. Can notify about core, plugin and theme updates.'=>'Envía un correo electrónico para avisarte si hay actualizaciones para tu sitio WordPress. Puede avisar de actualizaciones del núcleo, de plugins y de temas.','Scott Cariss'=>'Scott Cariss','https://wpun.cariss.dev/#about-the-developer'=>'https://wpun.cariss.dev/#about-the-developer','Enabled'=>'Activado','Send notifications through this channel'=>'Enviar notificaciones a través de este canal','(external link)'=>'(enlace externo)','About the plugin'=>'Acerca del plugin','WP Updates Notifier checks your site for WordPress core, plugin and theme updates and tells you about each new version once. It is free and open source, with no tracking and no account to sign up for.'=>'WP Updates Notifier comprueba si hay actualizaciones del núcleo de WordPress, de plugins y de temas en tu sitio y te avisa una sola vez de cada nueva versión. Es gratuito y de código abierto, sin seguimiento y sin necesidad de crear una cuenta.','Documentation'=>'Documentación','GitHub'=>'GitHub','WordPress.org'=>'WordPress.org','Help and bugs'=>'Ayuda y errores','Questions: ask in the %s.'=>'¿Preguntas? Hazlas en el %s.','support forum'=>'foro de soporte','Bugs and ideas: open an issue on %s.'=>'Errores e ideas: abre una incidencia en %s.','Security problems: please report them privately, as the %s explains.'=>'Problemas de seguridad: infórmalos de forma privada, como explica la %s.','security policy'=>'política de seguridad','Leave a review'=>'Deja una valoración','Like it? %s. It helps other people find the plugin.'=>'¿Te gusta? %s. Ayuda a que otras personas encuentren el plugin.','Leave a review on WordPress.org'=>'Deja una valoración en WordPress.org','Donate'=>'Donar','WP Updates Notifier is free. If it saves you time and you would like to say thanks, a donation helps keep it maintained.'=>'WP Updates Notifier es gratuito. Si te ahorra tiempo y quieres dar las gracias, una donación ayuda a mantenerlo.','Ways to donate'=>'Formas de donar','About the developer'=>'Acerca del desarrollador','I have been a software engineer for over 20 years and I am now a Lead Platform Engineer, building the platforms other engineers ship on. I first released WP Updates Notifier on WordPress.org in 2011, and it now runs on around 30,000 sites.'=>'Llevo más de 20 años como ingeniero de software y ahora soy Lead Platform Engineer: construyo las plataformas sobre las que otros ingenieros publican su trabajo. Publiqué WP Updates Notifier por primera vez en WordPress.org en 2011 y hoy funciona en unos 30.000 sitios.','Scott Cariss on GitHub'=>'Scott Cariss en GitHub','Scott Cariss on LinkedIn'=>'Scott Cariss en LinkedIn','For power users'=>'Para usuarios avanzados','You can hide this tab with a line in wp-config.php:'=>'Puedes ocultar esta pestaña con una línea en wp-config.php:','The setting is never stored and has no field on the settings screen. An environment variable, a configuration source or the sc_wpun_config_value filter can set it too. If you hide the tab, please consider a donation or a review in return.'=>'Este ajuste nunca se guarda y no tiene campo en la pantalla de ajustes. También puede establecerlo una variable de entorno, una fuente de configuración o el filtro sc_wpun_config_value. Si ocultas la pestaña, considera hacer una donación o dejar una valoración a cambio.','No channel modules are available.'=>'No hay módulos de canal disponibles.','Choose where the update notifications are to be sent.'=>'Elige dónde enviar los notificaciones de actualizaciones.','Cancel'=>'Cancelar','Add channel'=>'Añadir canal','Add %s channel'=>'Añadir canal de %s','Edit %s'=>'Editar %s','There is no such channel module.'=>'No existe ese módulo de canal.','There is no such channel.'=>'No existe ese canal.','%s is defined in code and cannot be changed here.'=>'%s está definido en el código y no se puede cambiar aquí.','Save channel'=>'Guardar canal','There is a problem'=>'Hay un problema','The channel was not saved. Please correct the following.'=>'El canal no se ha guardado. Corrige lo siguiente.','Set by %s'=>'Definido por %s','Channel'=>'Canal','ID'=>'ID','The id is made from the label when the channel is saved and cannot be changed afterwards.'=>'El ID se crea a partir de la etiqueta al guardar el canal y no se puede cambiar después.','Constants for this channel start with %s'=>'Las constantes de este canal empiezan por %s','Updates already waiting'=>'Actualizaciones ya pendientes','Don\'t send the updates that are already waiting'=>'No enviar las actualizaciones que ya están pendientes','Only updates that appear after the channel is switched on are sent. Applies when the channel is saved switched on.'=>'Solo se envían las actualizaciones que aparezcan después de activar el canal. Se aplica cuando el canal se guarda activado.','Routing'=>'Enrutamiento','On the General tab, plugins are not checked.'=>'En la pestaña General, no se comprueban los plugins.','On the General tab, only active plugins are checked, so "All" here acts like "Only active ones" for plugins.'=>'En la pestaña General solo se comprueban los plugins activos, así que aquí "Todos" equivale a "Solo los activos" para los plugins.','On the General tab, themes are not checked.'=>'En la pestaña General, no se comprueban los temas.','On the General tab, only active themes are checked, so "All" here acts like "Only active ones" for themes.'=>'En la pestaña General solo se comprueban los temas activos, así que aquí "Todos" equivale a "Solo los activos" para los temas.','On the General tab, WordPress updates are not checked.'=>'En la pestaña General, no se comprueban las actualizaciones de WordPress.','On the General tab, only major releases are checked.'=>'En la pestaña General solo se comprueban las versiones principales.','Settings'=>'Ajustes','Label'=>'Etiqueta','The settings are not valid.'=>'Los ajustes no son válidos.','%s added.'=>'%s añadido.','%s saved.'=>'%s guardado.','You are not allowed to do that.'=>'No tienes permiso para hacer eso.','Delete %s?'=>'¿Borrar %s?','Channels'=>'Canales','No channels are set up yet. A channel is where the update notifications are sent, for example an email address.'=>'Todavía no hay canales configurados. Un canal es el destino de los notificaciones de actualizaciones, por ejemplo, una dirección de correo electrónico.','Module'=>'Módulo','Last delivery'=>'Último envío','Unavailable channels'=>'Canales no disponibles','These channels belong to modules that need a newer version of WP Updates Notifier. Nothing is sent through them and their settings are kept.'=>'Estos canales pertenecen a módulos que necesitan una versión más reciente de WP Updates Notifier. No se envía nada a través de ellos y se conservan sus ajustes.','Status'=>'Estado','Unavailable: %s'=>'No disponible: %s','Defined in code'=>'Definido en el código','Show more details'=>'Mostrar más detalles','On'=>'Activado','Off'=>'Desactivado','Edit'=>'Editar','Send test to %s'=>'Enviar prueba a %s','Send test'=>'Enviar prueba','Duplicate %s'=>'Duplicar %s','Duplicate'=>'Duplicar','Disable %s'=>'Desactivar %s','Disable'=>'Desactivar','Enable %s'=>'Activar %s','Enable'=>'Activar','Delete %s'=>'Borrar %s','Delete'=>'Borrar','Delete the channel %s? Its settings and delivery history are removed. This cannot be undone.'=>'¿Borrar el canal %s? Se eliminarán sus ajustes y su historial de envíos. Esto no se puede deshacer.','No known item types'=>'No hay tipos de elementos conocidos','All updates'=>'Todas las actualizaciones','Held until %s'=>'Retenido hasta %s','Never'=>'Nunca','Sent %s'=>'Enviado el %s','Failed %1$s: %2$s'=>'Falló el %1$s: %2$s','Rate limited, next try after %s'=>'Límite de envíos alcanzado, próximo intento después del %s','%s cannot send a test message.'=>'%s no puede enviar un mensaje de prueba.','Test message sent through %s.'=>'Mensaje de prueba enviado a través de %s.','The test message could not be sent through %1$s: %2$s'=>'No se ha podido enviar el mensaje de prueba a través de %1$s: %2$s','%1$s cannot be switched here: set by %2$s.'=>'%1$s no se puede activar ni desactivar aquí: definido por %2$s.','%s enabled.'=>'%s activado.','%s disabled.'=>'%s desactivado.','%s (copy)'=>'%s (copia)','Channel duplicated as %s.'=>'Canal duplicado como %s.','%s deleted.'=>'%s borrado.','Check for updates and notify now'=>'Comprobar actualizaciones y avisar ahora','Only updates that were not notified yet are sent. To try a channel, send a test message from the %s.'=>'Solo se envían las actualizaciones de las que aún no se ha avisado. Para probar un canal, envía un mensaje de prueba desde la %s.','Channels tab'=>'pestaña Canales','Checked just now. Nothing was sent because no channel is enabled.'=>'Comprobado ahora mismo. No se ha enviado nada porque no hay ningún canal activado.','Checked just now. Nothing new to send.'=>'Comprobado ahora mismo. No hay nada nuevo que enviar.','%1$s (until %2$s)'=>'%1$s (hasta %2$s)','Checked just now. Held: %s'=>'Comprobado ahora mismo. Retenido: %s','Checked just now. Sent to %d channel.'=>'Comprobado ahora mismo. Enviado a %d canal.' . "\0" . 'Comprobado ahora mismo. Enviado a %d canales.','Checked just now. %1$d channel failed: %2$s'=>'Comprobado ahora mismo. Ha fallado %1$d canal: %2$s' . "\0" . 'Comprobado ahora mismo. Han fallado %1$d canales: %2$s','Checked just now. Sent to %1$d channel; %2$d failed: %3$s'=>'Comprobado ahora mismo. Enviado a %1$d canal; %2$d con errores: %3$s' . "\0" . 'Comprobado ahora mismo. Enviado a %1$d canales; %2$d con errores: %3$s','Held: %s'=>'Retenido: %s','Error:'=>'Error:','Clear the saved value'=>'Borrar el valor guardado','Clear the saved value of %s'=>'Borrar el valor guardado de %s','A value is saved. Leave this empty to keep it, or type a new value to replace it.'=>'Hay un valor guardado. Deja esto vacío para conservarlo o escribe un nuevo valor para sustituirlo.','(required)'=>'(obligatorio)','That plugin or theme is not installed.'=>'Ese plugin o tema no está instalado.','No update is waiting for %s, so there is no version to skip.'=>'No hay ninguna actualización pendiente para %s, así que no hay versión que omitir.','A newer version of %s is waiting than the one on the page. Reload the page and try again.'=>'Hay una versión de %s más reciente que la que se ve en la página. Recarga la página e inténtalo de nuevo.','Update notifications for %1$s are snoozed until %2$s.'=>'Las notificaciones de actualización de %1$s están pospuestas hasta %2$s.','Update notifications for %1$s version %2$s are skipped, until %3$s at the latest.'=>'Las notificaciones de actualización de %1$s versión %2$s se omiten, como máximo hasta %3$s.','Update notifications for %s are muted.'=>'Las notificaciones de actualización de %s están silenciadas.','Update notifications for %1$s version %2$s are skipped.'=>'Las notificaciones de actualización de %1$s versión %2$s se omiten.','Update notifications for %s are on again.'=>'Las notificaciones de actualización de %s vuelven a estar activadas.','Muted'=>'Silenciados','A muted plugin or theme is left out of the update notifications. WordPress\'s own update notices, emails and automatic updates are not affected.'=>'Un plugin o tema silenciado se deja fuera de las notificaciones de actualización. Los avisos, los correos y las actualizaciones automáticas del propio WordPress no se ven afectados.','Nothing is muted. Muting a plugin or theme stops the update notifications about it, always or for the version that is waiting. Mute a plugin from the %s, or a plugin or theme with the form below.'=>'No hay nada silenciado. Silenciar un plugin o tema detiene las notificaciones de sus actualizaciones, para siempre o solo para la versión pendiente. Silencia un plugin desde la %s, o un plugin o tema con el formulario de abajo.','Plugins screen'=>'pantalla de plugins','Muted plugins and themes'=>'Plugins y temas silenciados','Name'=>'Nombre','Mute'=>'Silencio','Muted by'=>'Silenciado por','Unmute'=>'Reactivar','Plugin'=>'Plugin','Theme'=>'Tema','Set in code'=>'Definido en el código','Unknown user'=>'Usuario desconocido','from %s'=>'desde %s','%1$s, %2$s'=>'%1$s, %2$s','Always'=>'Siempre','Version %s'=>'Versión %s','Snoozed until %s'=>'Pospuestas hasta %s','Version %1$s, until %2$s'=>'Versión %1$s, hasta %2$s','%s, not installed'=>'%s, no instalado','No update waiting'=>'Ninguna actualización pendiente','Update to %s waiting'=>'Actualización a %s pendiente','Set in code, it cannot be unmuted here'=>'Definido en el código, no se puede reactivar aquí','You may not unmute'=>'No tienes permiso para reactivar','Unmute %s'=>'Reactivar %s','Mute a plugin or theme'=>'Silenciar un plugin o tema','Every installed plugin and theme is muted.'=>'Todos los plugins y temas instalados están silenciados.','Plugin or theme'=>'Plugin o tema','Plugins'=>'Plugins','Themes'=>'Temas','What to mute'=>'Qué silenciar','Skip the waiting version'=>'Omitir la versión pendiente','Notifications start again when a newer version than the waiting one is offered. It needs an update to be waiting.'=>'Las notificaciones se reanudan cuando se ofrece una versión más reciente que la pendiente. Hace falta que haya una actualización pendiente.','Snooze until'=>'Posponer hasta','Optional, in the time zone of the site. Notifications start again at that time. With "Skip the waiting version" they start again at that time or when a newer version is offered, whichever is first.'=>'Opcional, en la zona horaria del sitio. Las notificaciones se reanudan en ese momento. Con «Omitir la versión pendiente» se reanudan en ese momento o cuando se ofrece una versión más reciente, lo que ocurra primero.','Choose a plugin or theme to mute.'=>'Elige un plugin o tema para silenciar.','Enter the end of the snooze as a date and time.'=>'Introduce el final del aplazamiento como fecha y hora.','The end of the snooze must be in the future.'=>'El final del aplazamiento debe estar en el futuro.','WP Updates Notifier now runs for the whole network, and only when it is network-activated. Until it is, it sends no notifications for this site or any other.'=>'WP Updates Notifier ahora funciona para toda la red, y solo cuando está activado en la red. Hasta entonces, no envía avisos ni para este sitio ni para ningún otro.','WP Updates Notifier is not network-activated'=>'WP Updates Notifier no está activado en la red','Go to the network plugins'=>'Ir a los plugins de la red','Updates Notifier'=>'Updates Notifier','This add-on\'s WP Updates Notifier API requirement (%s) could not be read.'=>'No se ha podido leer el requisito de la API de WP Updates Notifier de este complemento (%s).','This add-on needs the WP Updates Notifier API %1$s. This site has %2$s. Update WP Updates Notifier.'=>'Este complemento necesita la API de WP Updates Notifier %1$s. Este sitio tiene la %2$s. Actualiza WP Updates Notifier.','Mute update notifications for %s'=>'Silenciar las notificaciones de actualización de %s','Mute update notifications'=>'Silenciar notificaciones de actualización','Unmute update notifications for %s'=>'Reactivar las notificaciones de actualización de %s','Unmute update notifications'=>'Reactivar notificaciones de actualización','Notifications snoozed until %s'=>'Notificaciones pospuestas hasta %s','Notifications for version %1$s are skipped until %2$s'=>'Las notificaciones de la versión %1$s se omiten hasta %2$s','Update notifications muted'=>'Notificaciones de actualización silenciadas','Notifications for version %s are skipped'=>'Se omiten las notificaciones de la versión %s','%s (set in code)'=>'%s (definido en el código)','Don\'t notify me about version %s'=>'No avisarme de la versión %s','Snooze update notifications for %s'=>'Posponer las notificaciones de actualización: %s','Snooze:'=>'Posponer:','Undo snoozing'=>'Deshacer el aplazamiento','Undo skipping the version'=>'Deshacer la omisión de la versión','Undo'=>'Deshacer','Notifications for version %s are skipped.'=>'Se omiten las notificaciones de la versión %s.','Update notifications muted for %d plugin.'=>'Notificaciones de actualización silenciadas para %d plugin.' . "\0" . 'Notificaciones de actualización silenciadas para %d plugins.','Update notifications are on again for %d plugin.'=>'Notificaciones de actualización reactivadas para %d plugin.' . "\0" . 'Notificaciones de actualización reactivadas para %d plugins.','That length of snooze is not offered. Reload the page and try again.'=>'Esa duración no se ofrece. Recarga la página e inténtalo de nuevo.','Sorry, you are not allowed to access this page.'=>'Lo siento, no tienes permisos para acceder a esta página.','%1$s &lsaquo; %2$s'=>'%1$s &lsaquo; %2$s','Error: %s'=>'Error: %s','General'=>'General','About'=>'Acerca de','Settings sections'=>'Secciones de ajustes','Last checked: never'=>'Última comprobación: nunca','Last checked: %s'=>'Última comprobación: %s','Next check: not scheduled. Save the settings to schedule it.'=>'Próxima comprobación: no programada. Guarda los ajustes para programarla.','Next check: %s'=>'Próxima comprobación: %s','Save settings'=>'Guardar ajustes','%1$s at %2$s'=>'%1$s a las %2$s','Choose how often to check for updates.'=>'Elige con qué frecuencia comprobar si hay actualizaciones.','Choose whether to be told about WordPress updates.'=>'Elige si quieres recibir notificaciones de las actualizaciones de WordPress.','Choose whether to be told about plugin updates.'=>'Elige si quieres recibir notificaciones de las actualizaciones de plugins.','Choose whether to be told about theme updates.'=>'Elige si quieres recibir notificaciones de las actualizaciones de temas.','Choose whether to hide the update notices.'=>'Elige si quieres ocultar los avisos de actualización.','Choose whether to include download links.'=>'Elige si quieres incluir los enlaces de descarga.','Choose a value for %s.'=>'Elige un valor para %s.','This is a test message from WP Updates Notifier.'=>'Este es un mensaje de prueba de WP Updates Notifier.','%s (no longer available)'=>'%s (ya no está disponible)','The saved frequency is no longer available on this site, so checks run at the interval they were last scheduled with. Choose a frequency and save to change it.'=>'La frecuencia guardada ya no está disponible en este sitio, así que las comprobaciones se ejecutan con el intervalo con el que se programaron por última vez. Elige una frecuencia y guarda para cambiarla.','Scheduled checks run WordPress\'s automatic updates first, so updates it installs by itself are not reported.'=>'Las comprobaciones programadas ejecutan primero las actualizaciones automáticas de WordPress, así que no se avisa de las actualizaciones que instala por sí mismo.','Some paid plugins and themes put a licence key or a private token in their download address. With this on, that address is sent to everyone who receives the notifications, on every channel.'=>'Algunos plugins y temas de pago incluyen una clave de licencia o un token privado en su dirección de descarga. Con esta opción activada, esa dirección se envía a todas las personas que reciben las notificaciones, en todos los canales.','The display "%1$s" cannot show an on or off value, so "%2$s" is used.'=>'La visualización "%1$s" no puede mostrar un valor de activado o desactivado, así que se usa "%2$s".','Yes'=>'Sí','No'=>'No','A channel type may only contain lower case letters, digits and underscores.'=>'Un tipo de canal solo puede contener letras minúsculas, números y guiones bajos.','A channel of type "%s" is already registered.'=>'Ya hay registrado un canal del tipo "%s".','Needs WP Updates Notifier API %1$s; this site has %2$s. Update WP Updates Notifier.'=>'Necesita la API de WP Updates Notifier %1$s; este sitio tiene la %2$s. Actualiza WP Updates Notifier.','Its API requirement "%s" could not be read.'=>'No se ha podido leer su requisito de API "%s".','An instance defined in code cannot be saved.'=>'Una instancia definida en el código no se puede guardar.','An instance defined in code cannot be deleted.'=>'Una instancia definida en el código no se puede borrar.','The field "%2$s" of the "%1$s" channel cannot be supplied from outside the database: the name "enabled" is reserved, and names may only contain a-z, 0-9 and single underscores.'=>'El campo "%2$s" del canal "%1$s" no se puede proporcionar desde fuera de la base de datos: el nombre "enabled" está reservado y los nombres solo pueden contener a-z, 0-9 y guiones bajos sueltos.','The value is not valid for this channel.'=>'El valor no es válido para este canal.','The value could not be checked: %s was thrown.'=>'No se ha podido comprobar el valor: se ha lanzado %s.','constant SC_WPUN_CHANNELS'=>'la constante SC_WPUN_CHANNELS','The constant must be a JSON string.'=>'La constante debe ser una cadena JSON.','The value must be a JSON string.'=>'El valor debe ser una cadena JSON.','The JSON must be a list of channels.'=>'El JSON debe ser una lista de canales.','the sc_wpun_channels filter'=>'el filtro sc_wpun_channels','Channel %d repeats the id of an earlier channel and was skipped.'=>'El canal %d repite el ID de un canal anterior y se ha omitido.','Channel %d is not valid and was skipped.'=>'El canal %d no es válido y se ha omitido.','Some configuration values supplied from outside the database are not valid. Invalid settings fall back to the saved value; a channel with an invalid value does not send until it is fixed.'=>'Algunos valores de configuración proporcionados desde fuera de la base de datos no son válidos. Los ajustes no válidos vuelven al valor guardado; un canal con un valor no válido no envía nada hasta que se corrija.','WP Updates Notifier cannot use some configuration values'=>'WP Updates Notifier no puede usar algunos valores de configuración','Some values supplied by constants, environment variables or other sources are not valid. Invalid settings fall back to the saved value; a channel with an invalid value does not send until it is fixed.'=>'Algunos valores proporcionados por constantes, variables de entorno u otras fuentes no son válidos. Los ajustes no válidos vuelven al valor guardado; un canal con un valor no válido no envía nada hasta que se corrija.','Review the notification settings'=>'Revisar los ajustes de notificaciones','the sc_wpun_config_value filter'=>'el filtro sc_wpun_config_value','The value is not valid for this setting, so the default is used.'=>'El valor no es válido para este ajuste, así que se usa el predeterminado.','The value is not valid for this setting, so the saved one is used.'=>'El valor no es válido para este ajuste, así que se usa el guardado.','The value is not valid for this field.'=>'El valor no es válido para este campo.','The value is not a recognised on or off value (1, true, yes, on, 0, false, no, off), so environment variables are not read.'=>'El valor no es un valor reconocido de activado o desactivado (1, true, yes, on, 0, false, no, off), así que no se leen las variables de entorno.','Every entry must implement WPUN\\Config_Source.'=>'Cada entrada debe implementar WPUN\\Config_Source.','a configuration source'=>'una fuente de configuración','constant %s'=>'la constante %s','This channel cannot send a test message.'=>'Este canal no puede enviar un mensaje de prueba.','This channel is switched off.'=>'Este canal está desactivado.','The "%s" channel did not return a Delivery_Result.'=>'El canal "%s" no ha devuelto un Delivery_Result.','Not held back, because this is a test message.'=>'No se retuvo, porque es un mensaje de prueba.','The "%s" channel failed with an error.'=>'El canal "%s" ha fallado con un error.','The channel is misconfigured: %s is not valid.'=>'El canal está mal configurado: %s no es válido.','The "%1$s" channel is not available: %2$s'=>'El canal "%1$s" no está disponible: %2$s','The "%s" channel is not available.'=>'El canal "%s" no está disponible.','The display "%1$s" cannot show several choices, so "%2$s" is used.'=>'La visualización "%1$s" no puede mostrar varias opciones, así que se usa "%2$s".','The display "%1$s" cannot show a single choice, so "%2$s" is used.'=>'La visualización "%1$s" no puede mostrar una sola opción, así que se usa "%2$s".','environment variable %s'=>'la variable de entorno %s','The field type "%s" must be an array with a callable "render" and a callable "sanitize", so it is ignored.'=>'El tipo de campo "%s" debe ser un array con un "render" invocable y un "sanitize" invocable, así que se ignora.','No field type "%s" is registered, so the field is ignored. Register it with the sc_wpun_field_types filter.'=>'No hay ningún tipo de campo "%s" registrado, así que se ignora el campo. Regístralo con el filtro sc_wpun_field_types.','Enter a full web address that starts with http:// or https://.'=>'Introduce una dirección web completa que empiece por http:// o https://.','One or more email addresses are not valid.'=>'Una o más direcciones de correo electrónico no son válidas.','Enter a whole number.'=>'Introduce un número entero.','Enter a number that is at least %d.'=>'Introduce un número igual o mayor que %d.','Enter a number that is at most %d.'=>'Introduce un número igual o menor que %d.','The choice for "%s" is not valid.'=>'La opción para "%s" no es válida.','%s is required.'=>'%s es obligatorio.','The value for "%s" is not valid.'=>'El valor para "%s" no es válido.','WordPress'=>'WordPress','The mute was refused.'=>'Se rechazó el silenciamiento.','The mute was refused: it is for another item.'=>'Se rechazó el silenciamiento: es para otro elemento.','That item is not muted.'=>'Ese elemento no está silenciado.','That mute is set in code and cannot be removed here.'=>'Ese silenciamiento está definido en el código y no se puede quitar aquí.','Removing the mute was refused.'=>'Se rechazó quitar el silenciamiento.','WordPress core cannot be muted. Use the core notification setting instead.'=>'El núcleo de WordPress no se puede silenciar. Usa en su lugar el ajuste de notificaciones del núcleo.','That kind of item cannot be muted.'=>'Ese tipo de elemento no se puede silenciar.','Say which item to mute.'=>'Indica qué elemento silenciar.','The version to skip cannot be empty.'=>'La versión que se omite no puede estar vacía.','That mute is set in code and cannot be changed here.'=>'Ese silenciamiento está definido en el código y no se puede cambiar aquí.','The end of the mute must be in the future.'=>'El final del silencio debe estar en el futuro.','1 day'=>'1 día','1 week'=>'1 semana','30 days'=>'30 días','where a mute was set fromPlugins screen'=>'la pantalla de plugins','where a mute was set fromMuted tab'=>'la pestaña Silenciados','where a mute was set fromWP-CLI'=>'WP-CLI','where a mute was set fromCode'=>'el código','…and %d more'=>'…y %d más' . "\0" . '…y %d más','Reminder: these updates are still waiting for %1$s (%2$s)'=>'Recordatorio: estas actualizaciones siguen pendientes en %1$s (%2$s)','There are updates available for %1$s (%2$s)'=>'Hay actualizaciones disponibles para %1$s (%2$s)','%1$s from version %2$s to %3$s'=>'%1$s de la versión %2$s a la %3$s','Please visit %s to update.'=>'Visita %s para actualizar.','Go to the Updates screen to update.'=>'Ve a la pantalla de Actualizaciones para actualizar.','Details'=>'Detalles','Changelog'=>'Registro de cambios','Download'=>'Descarga','%s details'=>'Detalles de %s','%s changelog'=>'Registro de cambios de %s','%s download'=>'Descarga de %s','WP Updates Notifier: updates available for %s'=>'WP Updates Notifier: actualizaciones disponibles para %s','Some notification modules need a newer version of WP Updates Notifier and are switched off. Their settings have been kept.'=>'Algunos módulos de notificación necesitan una versión más reciente de WP Updates Notifier y están desactivados. Se han conservado sus ajustes.','Some WP Updates Notifier modules need a newer version'=>'Algunos módulos de WP Updates Notifier necesitan una versión más reciente','Some notification modules need a newer version of WP Updates Notifier than this site has, so they are switched off. Their settings have been kept.'=>'Algunos módulos de notificación necesitan una versión de WP Updates Notifier más reciente que la de este sitio, así que están desactivados. Se han conservado sus ajustes.','Update WP Updates Notifier'=>'Actualizar WP Updates Notifier','Item types'=>'Tipos de elementos','Leave every box unticked to receive all types, including ones added later.'=>'Deja todas las casillas sin marcar para recibir todos los tipos, incluidos los que se añadan más adelante.','Plugins and themes'=>'Plugins y temas','Applies after the plugin and theme settings on the General tab.'=>'Se aplica después de los ajustes de plugins y temas de la pestaña General.','All'=>'Todos','Only active ones'=>'Solo los activos','WordPress updates'=>'Actualizaciones de WordPress','Applies after the WordPress updates setting on the General tab.'=>'Se aplica después del ajuste de actualizaciones de WordPress de la pestaña General.','Only major releases'=>'Solo las versiones principales','Reminders'=>'Recordatorios','Repeat every update that is still waiting, in one message, until it is installed. New updates are still sent at once.'=>'Repetir cada actualización que siga pendiente, en un solo mensaje, hasta que se instale. Las nuevas actualizaciones se siguen enviando al momento.','Daily'=>'Diariamente','Weekly'=>'Semanalmente','Every check'=>'En cada comprobación','Frequency to check'=>'Frecuencia de comprobación','Update notice'=>'Aviso de actualización','Hide the WordPress update notice from users who cannot update WordPress'=>'Ocultar el aviso de actualización de WordPress a los usuarios que no pueden actualizar WordPress','Download links'=>'Enlaces de descarga','Include download links in notifications'=>'Incluir enlaces de descarga en las notificaciones','About tab'=>'Pestaña Acerca de','Notify about WordPress updates?'=>'¿Avisar de las actualizaciones de WordPress?','Yes, but only major releases'=>'Sí, pero solo las versiones principales','Notify about plugin updates?'=>'¿Avisar de las actualizaciones de plugins?','Notify about theme updates?'=>'¿Avisar de las actualizaciones de temas?','Yes, but only active plugins'=>'Sí, pero solo los plugins activos','Yes, but only active themes'=>'Sí, pero solo los temas activos','WP Updates Notifier checks for updates'=>'WP Updates Notifier comprueba las actualizaciones','WP-Cron is switched off for WP Updates Notifier'=>'WP-Cron está desactivado para WP Updates Notifier','WP Updates Notifier has a channel to send through'=>'WP Updates Notifier tiene un canal por el que enviar','The modules of the WP Updates Notifier channels are available'=>'Los módulos de los canales de WP Updates Notifier están disponibles','The last notification of each WP Updates Notifier channel was delivered'=>'El último envío de cada canal de WP Updates Notifier se realizó correctamente','The update check is not scheduled, so no update will be reported.'=>'La comprobación de actualizaciones no está programada, así que no se informará de ninguna actualización.','The update checks are not running. The next one is long overdue and none ran lately. WP-Cron may not be running on this site.'=>'Las comprobaciones de actualizaciones no se están ejecutando. La siguiente está muy retrasada y no se ha ejecutado ninguna recientemente. Es posible que WP-Cron no se esté ejecutando en este sitio.','The update check is scheduled and running.'=>'La comprobación de actualizaciones está programada y en ejecución.','WP Updates Notifier is not checking for updates'=>'WP Updates Notifier no está comprobando las actualizaciones','WP Updates Notifier checks run from a server cron'=>'Las comprobaciones de WP Updates Notifier se ejecutan desde un cron del servidor','WP-Cron is switched off, and the update checks are running from a server cron.'=>'WP-Cron está desactivado y las comprobaciones de actualizaciones se ejecutan desde un cron del servidor.','WP-Cron is switched off, so WP Updates Notifier may not check'=>'WP-Cron está desactivado, por lo que WP Updates Notifier podría no comprobar','DISABLE_WP_CRON is set and no update check ran lately. Make a server cron request wp-cron.php regularly, or run "wp updates-notifier check" from a server cron.'=>'DISABLE_WP_CRON está definido y no se ha ejecutado ninguna comprobación de actualizaciones recientemente. Haz que un cron del servidor solicite wp-cron.php con regularidad, o ejecuta "wp updates-notifier check" desde un cron del servidor.','At least one channel is switched on and can send.'=>'Al menos un canal está activado y puede enviar.','WP Updates Notifier has no channel to send through'=>'WP Updates Notifier no tiene ningún canal por el que enviar','No channel is switched on and able to send, so nothing will be sent. Switch a channel on if you want to be told about updates.'=>'Ningún canal está activado y en condiciones de enviar, así que no se enviará nada. Activa un canal si quieres recibir avisos de actualizaciones.','Every channel that is switched on has its module.'=>'Cada canal activado tiene su módulo.','Some WP Updates Notifier channels cannot send'=>'Algunos canales de WP Updates Notifier no pueden enviar','These channels are switched on, but their module is not available, so nothing is sent through them. Activate the add-on that provides the module, or switch the channel off.'=>'Estos canales están activados, pero su módulo no está disponible, así que no se envía nada por ellos. Activa el complemento que proporciona el módulo o desactiva el canal.','No channel that is switched on failed its last delivery.'=>'Ningún canal activado falló en su último envío.','Some WP Updates Notifier channels failed to deliver'=>'Algunos canales de WP Updates Notifier no pudieron enviar','The last delivery of these channels failed. The update will be tried again at the next check.'=>'El último envío de estos canales falló. Se volverá a intentar con la actualización en la próxima comprobación.','Check frequency'=>'Frecuencia de comprobación','Next check'=>'Próxima comprobación','Last check'=>'Última comprobación','WP-Cron switched off (DISABLE_WP_CRON)'=>'WP-Cron desactivado (DISABLE_WP_CRON)','set in code'=>'definido en el código','None'=>'Ninguno','Disabled by DISALLOW_FILE_MODS'=>'Desactivadas por DISALLOW_FILE_MODS','Disabled by AUTOMATIC_UPDATER_DISABLED or the automatic_updater_disabled filter'=>'Desactivadas por AUTOMATIC_UPDATER_DISABLED o el filtro automatic_updater_disabled','Version control checkout'=>'Copia de un sistema de control de versiones','Can run'=>'Pueden ejecutarse','WordPress automatic updates'=>'Actualizaciones automáticas de WordPress','Configuration problem'=>'Problema de configuración','Availability'=>'Disponibilidad','Next try after'=>'Próximo intento después de','Held until'=>'Retenido hasta','Frequency: %s'=>'Frecuencia: %s','Last check: %s'=>'Última comprobación: %s','Email notifications continue as before.'=>'Las notificaciones por correo electrónico siguen como antes.','Email notifications are switched off, so this site currently sends no update notifications. You can turn them on at %s'=>'Las notificaciones por correo electrónico están desactivadas, así que este sitio no envía ahora mismo ninguna notificación de actualizaciones. Puedes activarlas en %s','Slack notifications are not supported in this version of WP Updates Notifier. Your Slack settings have been kept.'=>'Las notificaciones de Slack no son compatibles con esta versión de WP Updates Notifier. Se han conservado tus ajustes de Slack.','New notification channels and features are coming in future releases.'=>'En próximas versiones llegarán nuevos canales de notificación y nuevas funciones.','WP Updates Notifier: Slack notifications are no longer supported'=>'WP Updates Notifier: las notificaciones de Slack ya no son compatibles','Slack notifications are no longer supported'=>'Las notificaciones de Slack ya no son compatibles','Dismiss this notice'=>'Descartar este aviso','Slack notifications are no longer supported by WP Updates Notifier'=>'WP Updates Notifier ya no es compatible con las notificaciones de Slack','Slack notifications are not supported in this version of WP Updates Notifier, so none are sent. Your Slack settings have been kept.'=>'Las notificaciones de Slack no son compatibles con esta versión de WP Updates Notifier, así que no se envía ninguna. Se han conservado tus ajustes de Slack.','always'=>'siempre','version %s'=>'versión %s','not scheduled'=>'no programado','never'=>'nunca','rejected: %s'=>'rechazado: %s','unknown module'=>'módulo desconocido','success'=>'correcto','failure'=>'error','not set'=>'sin establecer','set'=>'establecido','The filter must return a WPUN\\Notification.'=>'El filtro debe devolver un WPUN\\Notification.','Automatic updates are on, but WordPress has not installed this update yet.'=>'Las actualizaciones automáticas están activadas, pero WordPress aún no ha instalado esta actualización.','Compatibility with WordPress %s: unknown'=>'Compatibilidad con WordPress %s: desconocida','Compatibility with WordPress %s: tested by its author'=>'Compatibilidad con WordPress %s: probada por su autor','Compatibility with WordPress %1$s: not tested yet (tested up to %2$s)'=>'Compatibilidad con WordPress %1$s: aún no probada (probada hasta la %2$s)','Warning: this version needs PHP %1$s; the site runs PHP %2$s.'=>'Aviso: esta versión necesita PHP %1$s; el sitio usa PHP %2$s.','Warning: this version needs WordPress %1$s; the site runs WordPress %2$s.'=>'Aviso: esta versión necesita WordPress %1$s; el sitio usa WordPress %2$s.','The version "%s" could not be read. Use one to three numbers, such as "1.2.0".'=>'No se ha podido leer la versión "%s". Usa de uno a tres números, como "1.2.0".','The version constraint "%s" could not be read. Use Composer syntax, such as "^1.0" or ">=1.0 <2.0".'=>'No se ha podido leer la restricción de versión "%s". Usa la sintaxis de Composer, como "^1.0" o ">=1.0 <2.0".','No channel instance is switched on and available, so there is nobody to notify.'=>'Ninguna instancia de canal está activada y disponible, así que no hay nadie a quien avisar.','%d channel instance failed.'=>'%d instancia de canal ha fallado.' . "\0" . '%d instancias de canal han fallado.','Dry run finished, nothing was sent or changed. %d channel instance would be sent a message.'=>'Simulacro terminado, no se envió ni cambió nada. Se enviaría un mensaje a %d instancia de canal.' . "\0" . 'Simulacro terminado, no se envió ni cambió nada. Se enviaría un mensaje a %d instancias de canal.','Check finished. %d channel instance was sent a message.'=>'Comprobación terminada. Se envió un mensaje a %d instancia de canal.' . "\0" . 'Comprobación terminada. Se envió un mensaje a %d instancias de canal.','There is no channel instance "%s".'=>'No existe la instancia de canal «%s».','test message sent'=>'mensaje de prueba enviado','No channel instance is switched on, available and able to send a test message.'=>'Ninguna instancia de canal está activada, disponible y en condiciones de enviar un mensaje de prueba.','%d test message could not be sent.'=>'No se pudo enviar %d mensaje de prueba.' . "\0" . 'No se pudieron enviar %d mensajes de prueba.','%d test message sent.'=>'Se envió %d mensaje de prueba.' . "\0" . 'Se enviaron %d mensajes de prueba.','Schedule'=>'Programación','Settings of %s'=>'Ajustes de %s','Pending updates'=>'Actualizaciones pendientes','%1$s (%2$s)'=>'%1$s (%2$s)','%s is already muted that way.'=>'%s ya está silenciado de ese modo.','Use --for or --until-date, not both.'=>'Usa --for o --until-date, no ambos.','--for must be a whole number and h, d or w, for example 12h, 3d or 2w.'=>'--for debe ser un número entero con h, d o w, por ejemplo 12h, 3d o 2w.','--until-date must be a date as YYYY-MM-DD or YYYY-MM-DD HH:MM, in the site\'s timezone.'=>'--until-date debe ser una fecha como AAAA-MM-DD o AAAA-MM-DD HH:MM, en la zona horaria del sitio.','--until-date must be in the future.'=>'--until-date debe estar en el futuro.','%s is not muted.'=>'%s no está silenciado.','Say whether the names are plugins or themes, then one or more names.'=>'Indica si los nombres son de plugins o de temas, y después uno o más nombres.','The plugin "%s" is not installed.'=>'El plugin «%s» no está instalado.','The theme "%s" is not installed.'=>'El tema «%s» no está instalado.','%1$d of %2$d could not be changed.'=>'%1$d de %2$d no se pudieron cambiar.','%1$s cannot be used: %2$s.'=>'%1$s no se puede usar: %2$s.','%s is switched off.'=>'%s está desactivado.','switched off'=>'desactivado','waiting until %s'=>'en espera hasta %s','recorded without sending'=>'registrado sin enviar','would send a reminder with %d item'=>'enviaría un recordatorio con %d elemento' . "\0" . 'enviaría un recordatorio con %d elementos','sent a reminder with %d item'=>'recordatorio enviado con %d elemento' . "\0" . 'recordatorio enviado con %d elementos','would send %d item'=>'enviaría %d elemento' . "\0" . 'enviaría %d elementos','sent %d item'=>'%d elemento enviado' . "\0" . '%d elementos enviados','failed: %s'=>'falló: %s','the routing failed'=>'falló el enrutamiento','nothing new'=>'nada nuevo','Email'=>'Correo electrónico','Sends the notification to one or more email addresses.'=>'Envía la notificación a una o más direcciones de correo electrónico.','Send to'=>'Enviar a','Separate multiple email addresses with a comma (,).'=>'Separa varias direcciones de correo electrónico con una coma (,).','From address'=>'Dirección del remitente','Leave empty to use the WordPress default. Only set an address at a domain this site is allowed to send mail for.'=>'Déjalo vacío para usar el valor predeterminado de WordPress. Indica solo una dirección de un dominio desde el que este sitio tenga permiso para enviar correo.','Reply-To address'=>'Dirección de respuesta (Reply-To)','Format'=>'Formato','Plain text'=>'Texto sin formato','HTML'=>'HTML','Subject prefix'=>'Prefijo del asunto','One or more email addresses to send to are invalid.'=>'Una o más direcciones de correo electrónico de destino no son válidas.','Enter at least one valid email address to send to.'=>'Introduce al menos una dirección de correo electrónico de destino válida.','The email address is invalid.'=>'La dirección de correo electrónico no es válida.','The format must be plain text or HTML.'=>'El formato debe ser texto sin formato o HTML.','No email address to send to is set.'=>'No se ha establecido ninguna dirección de correo electrónico de destino.','WP Updates Notifier: test message for %s'=>'WP Updates Notifier: mensaje de prueba para %s','This is a test message from WP Updates Notifier for %1$s (%2$s). Update notifications for this site will be sent to this address.'=>'Este es un mensaje de prueba de WP Updates Notifier para %1$s (%2$s). Los notificaciones de actualizaciones de este sitio se enviarán a esta dirección.','WP Updates Notifier: reminder of updates waiting for %s'=>'WP Updates Notifier: recordatorio de actualizaciones pendientes en %s','WordPress could not send the email.'=>'WordPress no ha podido enviar el correo electrónico.','The email could not be sent (%s).'=>'No se pudo enviar el correo electrónico (%s).']];